import{_ as e,c as p,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"47、【困】 坎下兑上","description":"周易阐真 - 47、【困】 坎下兑上","frontmatter":{"title":"47、【困】 坎下兑上","description":"周易阐真 - 47、【困】 坎下兑上"},"headers":[],"relativePath":"zh/classics/chanzhen/048.md","filePath":"zh/classics/chanzhen/048.md"}'),s={name:"zh/classics/chanzhen/048.md"};function n(c,a,i,o,h,l){return t(),p("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：困，刚揜也。险以说，困而不失其所亨，其唯君子乎！贞大人吉，以刚中也。有言不信，尚口乃穷也。</p></blockquote><h1 id="_47、【困】-坎下兑上" tabindex="-1">47、【困】 坎下兑上 <a class="header-anchor" href="#_47、【困】-坎下兑上" aria-label="Permalink to “47、【困】 坎下兑上”">​</a></h1><p>初六：臀困于株木，入于幽谷，三岁不觌。</p><p>九二：困于酒食，朱绂方来，利用亨祀。征凶，无咎。</p><p>六三：困于石，据于蒺藜，入于其宫，不见其妻，凶。</p><p>九四：来徐徐，困于金车，吝，有终。</p><p>九五：劓刖，困于赤绂，乃徐有说，利用祭祀。</p><p>上六：困于葛藟，于臲危副本，曰动悔。有悔，征吉。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：泽无水，困。君子以致命遂志。</p><p>困者，穷也。上兑泽，下坎水，是泽漏水流，泽中无水，困之象也。</p><p>君子有见于此，知泽无水，则泽空；人无志，则道穷。以是致命而遂其志焉。致者，极也。命有气数之命，有道义之命。气数之命，天地所造，后天也；道义之命，造乎天地，先天也。先天之命，本是乾家之物，因交后天，入于坤宫，化而为坎，坎中一阳是也。此阳一陷，命宝潜藏，一身纯阴，困莫困于此矣。致命者，极其后天之命；遂志者，遂其先天之命。立志以致命，致命以遂志，气数在彼，造命在我，借后天，返先天，尽假命，立真命，无中生有，杀中求生，由困而通；亦如泽中无水，而又有水。卦象兑金自坎水而出，只取水中金一味者，亦不在此乎?</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>绂，音弗。刖，音月。说，音悦。臲，音业。危副本，音兀。</p><p>困者，穷难也。卦体下坎，一阳陷于二阴之中，上兑，一阴居于二阳之上，均系阴浸其阳，阳气不通之象，故谓困。卦德险中出悦，悦出于险，兼有济困之义。此磨砺身心之卦，承上萃卦而来。萃者，由顺得悦，所以攒簇药物，返本还元也。但能攒簇于平易，不能攒簇于艰险，仍是不能顺、不能悦。特以修道者平易之境，皆能有守，艰险之地，每多变志，或为衣食逼迫改念，或因疾病缠绵堕志，或因年老灰心，或因魔障歇工，诸如此类，皆是道心不力，为困所拘，终不成道。若果身困而心不困，境困而道不困，处险能悦，困中反有亨道矣。</p><p>虽然处险能悦，因为人所不及，亦必困所当困，若困所不当困，亦不得亨。盖困之亨道，在于得其正耳。以正处困，以正而亨，困而与时偕行也。与时偕行，惟俱中正之德之大人能之。特以大人者，大智若愚，大巧若拙，诸念不生，遇境难迁，素位而行，不愿乎外，不但所处得其吉，而且顺命能无咎。至于一切衣食之徒，不信于困，行险侥幸，稍不如意，形于辞色，怨天尤人，咎即随之，何能致吉?以正处困，险而能悦，则为大人；困而不信，悦以行险，则为小人。同一险也，同一悦也，而大人小人分之。修道者，遇困可不守其正乎?</p><p>初六，在困之初，其困不大，又近二阳，不宜受困，乃柔弱无刚，自暴自弃，甘居人下，如臀困于株,木入于幽谷矣。如此之人，不当困而困，虽三岁之久，终不能出险。此小困而自致大困者也。</p><p>九二，阳陷阴中，正在衣禄不足之时，如困于酒食也。幸其刚而得中，为道忘躯，身困而心不困，一日苦尽甜生，大道完成，方且服天衣、食天禄，如朱绂方来，修天爵而人爵即从之，先困后亨，理有可必。先困后亨之象，其利如用亨祀，以诚格天，久而见功，若正在困中，急欲出困，反招其凶，亦无咎，其困而不亨矣。此先困而后得亨者也。</p><p>六三，愚而自用，不知尊师敬友，为正人君子所嫌恶，如困于石，据于蒺藜，自入于困矣。如此之人，本无实学，自负有道，务外失内，亦如入于其宫，不见其妻，终亦必亡而已。此无困而自致困者也。</p><p>九四，出险地而居悦体，正当济困之时，乃刚居于柔，不能速济，似乎以柔伤刚，来徐徐如困于金章，而有吝道矣。然在困已久，不能直行其道，徐徐而来，终有如意之时。此有困而渐济困者也。</p><p>九五，阳刚中正，遇合不偶，有大作之道，而无大作之时，难行法财两用之事，不能随心所欲，如劓鼻刖足，赤绂受困。此抱道者之大困也。既在困中，未可强求于外，须当被褐怀玉，自苦自力，乃徐有悦也。徐悦之利，如用祭祀，以诚而入，日久功深，自有完成大道之时。此信困而渐出困者也。</p><p>上六，昏愚无知，自作聪明，妄猜私议，如葛藟挪扯，穿凿圣道，自谓得真，即便扭捏，日久受害，向前不得，退后不能，臲危副本 困危，是曰动悔。与其动而有悔，不若及早自悔，寻师访友，明而后行，始虽入于旁门，而受困致悔，终必闻乎大道，而征往得吉。此有悔而终出困者也。</p><p>六爻之用，有大人之困，有小人之困。大人之困，处险能悦，信其困而终无咎；小人之困，悦以行险，不信困而终有悔。困而致亨之道，险而能悦，待时守正，尽之矣。</p>',23)])])}const m=e(s,[["render",n]]);export{d as __pageData,m as default};
